import React from 'react';
import { graphql, Link, withPrefix } from 'gatsby';
import Layout from '../components/Layout';
import BentoTag from '../components/BentoTag';
import { useLanguage } from '../context/LanguageContext';
import aviationSvg from '../static/aviation.svg';
import dashboardGuidelinesSvg from '../static/dashboard-guidelines.svg';

const WorksPage = ({ data }) => {
  const { language, t } = useLanguage();
  const markdownNodes = data.allMarkdownRemark.nodes;

  // Filter content based on active language and section
  const worksData = markdownNodes.filter(
    (node) => node.frontmatter.section === 'works' && node.frontmatter.lang === language
  );

  // Exact slug-to-order map to create a perfectly balanced Bento Grid
  const orderMap = {
    'aircraft-on-ground': 1,
    'guideline-dashboards': 2,
    'decentralized-finance-dashboard': 3,
    'minimalist-ecommerce-platform': 4,
    'interactive-space-exhibition': 5
  };

  const sortedWorks = [...worksData].sort((a, b) => {
    const orderA = orderMap[a.frontmatter.slug] || 99;
    const orderB = orderMap[b.frontmatter.slug] || 99;
    return orderA - orderB;
  });

  const getCardImage = (slug) => {
    switch (slug) {
      case 'aircraft-on-ground':
        return aviationSvg;
      case 'guideline-dashboards':
        return dashboardGuidelinesSvg;
      default:
        return null;
    }
  };

  const getCardSizeClass = (slug) => {
    switch (slug) {
      case 'aircraft-on-ground':
        return 'tall-card row-span-2';
      case 'guideline-dashboards':
        return 'dashboard-card span-12 height-276';
      case 'decentralized-finance-dashboard':
        return 'span-12 height-276';
      case 'minimalist-ecommerce-platform':
      case 'interactive-space-exhibition':
      default:
        return 'span-10 height-300';
    }
  };
  // Lista de projetos visíveis no Sandbox (descomente para reexibir quando finalizar cada um)
  const visibleSandboxSlugs = [
    // 'logo-andressa-coelho',
    'logo-free-energy',
    // 'logo-amaranto',
    'logo-min-do',
  ];

  const sandboxData = markdownNodes.filter(
    (node) =>
      node.frontmatter.section === 'sandbox' &&
      node.frontmatter.lang === language &&
      visibleSandboxSlugs.includes(node.frontmatter.slug)
  );

  const sandboxOrderMap = {
    'logo-andressa-coelho': 1,
    'logo-free-energy': 2,
    'logo-amaranto': 3,
    'logo-min-do': 4,
  };

  const sortedSandbox = [...sandboxData].sort((a, b) => {
    const orderA = sandboxOrderMap[a.frontmatter.slug] || a.frontmatter.order || 99;
    const orderB = sandboxOrderMap[b.frontmatter.slug] || b.frontmatter.order || 99;
    return orderA - orderB;
  });

  const getSandboxImage = (slug, cover) => {
    if (cover) {
      return cover.startsWith('/') ? withPrefix(cover) : cover;
    }
    switch (slug) {
      case 'logo-andressa-coelho':
        return 'https://images.unsplash.com/photo-1626785774573-4b799315345d?q=80&w=600';
      case 'logo-free-energy':
        return 'https://images.unsplash.com/photo-1558655146-d09347e92766?q=80&w=600';
      case 'logo-amaranto':
        return 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=600';
      case 'logo-min-do':
        return 'https://images.unsplash.com/photo-1634017839464-5c339ebe3cb4?q=80&w=600';
      default:
        return 'https://images.unsplash.com/photo-1614850523459-c2f4c699c52e?q=80&w=600';
    }
  };

  return (
    <Layout>
      <div className="container works-page">
        <div className="works-header-intro">
          <h1>{t('works_title')}</h1>
          <p>{t('works_subtitle')}</p>
        </div>

        <div className="bento-grid">
          {/* Dynamically Rendered Work Cards */}
          {sortedWorks.map((work) => {
            const { slug } = work.frontmatter;
            const bgImage = getCardImage(slug);
            const sizeClass = getCardSizeClass(slug);

            if (slug === 'aircraft-on-ground') {
              return (
                <Link key={work.id} to={`/project/${slug}`} className={`bento-item img-card ${sizeClass}`}>
                  <div className="bento-item tag-card">
                    <BentoTag icon="MdDesignServices" text={t('bento_service_design_tag')} />
                  </div>
                  <div className="description-card">
                    <p>{t('bento_service_design_title')}</p>
                  </div>
                  <div className="content-card">
                    <svg width="118" height="118" viewBox="0 0 118 118" fill="none" xmlns="http://www.w3.org/2000/svg">
                      <g clipPath="url(#clip0_689_377_works)">
                        <path d="M110.92 80.1415L73.2091 17.6015C71.6842 15.2161 69.5833 13.2529 67.1 11.893C64.6168 10.5331 61.8311 9.82031 58.9999 9.82031C56.1687 9.82031 53.383 10.5331 50.8998 11.893C48.4165 13.2529 46.3156 15.2161 44.7908 17.6015L7.07992 80.1415C5.74777 82.3622 5.02372 84.8944 4.98056 87.4836C4.93741 90.0728 5.57668 92.6277 6.83409 94.8915C8.28785 97.4397 10.3921 99.5562 12.9317 101.025C15.4714 102.493 18.3554 103.261 21.2891 103.25H96.7108C99.6251 103.281 102.496 102.543 105.034 101.11C107.572 99.6768 109.687 97.5998 111.166 95.0882C112.46 92.8009 113.12 90.2092 113.077 87.5814C113.033 84.9536 112.289 82.3851 110.92 80.1415ZM102.562 90.2207C101.971 91.2365 101.113 92.0712 100.082 92.6345C99.0505 93.1978 97.8848 93.4683 96.7108 93.4165H21.2891C20.1151 93.4683 18.9493 93.1978 17.918 92.6345C16.8867 92.0712 16.0292 91.2365 15.4383 90.2207C15.0067 89.4733 14.7795 88.6254 14.7795 87.7624C14.7795 86.8993 15.0067 86.0515 15.4383 85.304L53.1983 22.7149C53.8768 21.8186 54.7537 21.0917 55.7603 20.5912C56.7669 20.0908 57.8758 19.8303 58.9999 19.8303C60.1241 19.8303 61.2329 20.0908 62.2395 20.5912C63.2461 21.0917 64.1231 21.8186 64.8016 22.7149L102.512 85.2549C102.961 86.0037 103.201 86.8584 103.21 87.7311C103.219 88.6038 102.995 89.4631 102.562 90.2207Z" fill="white" />
                        <path d="M59.0002 83.5833C61.7156 83.5833 63.9168 81.3821 63.9168 78.6667C63.9168 75.9513 61.7156 73.75 59.0002 73.75C56.2848 73.75 54.0835 75.9513 54.0835 78.6667C54.0835 81.3821 56.2848 83.5833 59.0002 83.5833Z" fill="white" />
                        <path d="M59.0002 39.3335C57.6962 39.3335 56.4456 39.8515 55.5236 40.7736C54.6015 41.6956 54.0835 42.9462 54.0835 44.2502V63.9168C54.0835 65.2208 54.6015 66.4714 55.5236 67.3934C56.4456 68.3155 57.6962 68.8335 59.0002 68.8335C60.3041 68.8335 61.5547 68.3155 62.4768 67.3934C63.3988 66.4714 63.9168 65.2208 63.9168 63.9168V44.2502C63.9168 42.9462 63.3988 41.6956 62.4768 40.7736C61.5547 39.8515 60.3041 39.3335 59.0002 39.3335Z" fill="white" />
                      </g>
                      <defs>
                        <clipPath id="clip0_689_377_works">
                          <rect width="118" height="118" fill="white" />
                        </clipPath>
                      </defs>
                    </svg>
                    <h3>Aircraft on Ground</h3>
                  </div>

                  <img src={bgImage} alt="Aviation" className="bento-image" />
                </Link>
              );
            }

            if (slug === 'guideline-dashboards') {
              return (
                <Link key={work.id} to={`/project/${slug}`} className={`bento-item img-card ${sizeClass}`}>
                  <div className="bento-item tag-card">
                    <BentoTag icon="MdSpaceDashboard" text={t('bento_dashboard_tag')} iconSize={18} />
                  </div>
                  <div className="description-card">
                    <p>{t('bento_dashboard_title')}</p>
                  </div>
                  <img src={bgImage} alt={t('bento_dashboard_title')} className="bento-image" />
                </Link>
              );
            }

            return (
              <div key={work.id} className={`bento-item ${sizeClass} coming-soon-card`}>
                <span className="coming-soon-label">{t('coming_soon')}</span>
              </div>
            );
          })}
        </div>

        {/* Sandbox Section */}
        <section className="sandbox-section" id="sandbox" style={{ marginTop: '80px', paddingTop: '60px', borderTop: '1px solid var(--border-color)' }}>
          <div className="works-header-intro" style={{ marginBottom: '40px' }}>
            <h2 style={{ fontSize: '3rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '-0.03em', marginBottom: '12px', color: 'var(--text-primary)' }}>
              {t('nav_sandbox')}
            </h2>
            <p style={{ color: 'var(--text-secondary)', fontSize: '1.2rem', maxWidth: '600px', lineHeight: 1.6 }}>
              {t('sandbox_subtitle')}
            </p>
          </div>

          <div className="bento-grid">
            {sortedSandbox.map((item) => {
              const { title, slug, category, tags, cover } = item.frontmatter;
              const bgImage = getSandboxImage(slug, cover);
              const isThemeBgCard = slug === 'logo-free-energy' || slug === 'logo-min-do';
              const isContainBgCard = slug === 'logo-min-do';

              return (
                <div
                  key={item.id}
                  className={`bento-item img-card span-5 height-300${isThemeBgCard ? ' theme-bg-card' : ''}${isContainBgCard ? ' contain-bg-card' : ''}`}
                >
                  <Link to={`/project/${slug}`} className="bento-card-link">
                    <div>
                      <div className="bento-card-category">{category}</div>
                      <h3 className="bento-card-title">{title}</h3>
                    </div>
                    <div className="bento-card-tags">
                      {tags && tags.slice(0, 3).map((tag, idx) => (
                        <span key={idx} className="bento-card-tag">{tag}</span>
                      ))}
                    </div>
                  </Link>
                  <div
                    className="bento-card-image-bg"
                    style={{ backgroundImage: `url(${bgImage})` }}
                  />
                </div>
              );
            })}
          </div>
        </section>
      </div>
    </Layout>
  );
};

export const query = graphql`
  query {
    allMarkdownRemark {
      nodes {
        id
        excerpt(pruneLength: 100)
        frontmatter {
          title
          slug
          lang
          section
          category
          tags
          cover
          order
        }
      }
    }
  }
`;

export default WorksPage;
